/* V0.8 PDF evidence lookup. Small page-derived index generated by CI from a
 * live manufacturer PDF. NOT a clinical instruction engine or a PDF chatbot.
 * No external API calls, and does not return content outside the indexed pages.
 */
(function(root,factory){
 const api=factory();
 if(typeof module!=="undefined"&&module.exports)module.exports=api;
 else root.MedtechPDFEvidence=api;
})(typeof globalThis!=="undefined"?globalThis:this,function(){
"use strict";
const normalize=x=>String(x||"").normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/ß/g,"ss").replace(/[^a-z0-9]+/g," ").trim();
const unsafe=/(?:alarm|alarme|warnsignal|beatmung|ventilation|therapie|dosier|bypass|interlock|schutzleiter).{0,100}(?:deaktiv|umgeh|ausschalt|abschalt|stumm|mute|suppress|silence|dosier|dosis|verander|andern|aender|veranderung|einstell|adjust|change|bypass|abschalt)|(?:deaktiv|umgeh|ausschalt|abschalt|stumm|mute|suppress|silence|bypass).{0,100}(?:alarm|warnsignal|schutzleiter|interlock)|(?:patientendaten|patientenakte|passwort|password|patient record)/;
const excluded=/\b(?:drager|draeger|vista|n-600|masimo|mindray|ukb|inventar|seriennummer|last serviced|wartungshistorie)\b/;
const generic=new Set("was ist eine einen ein wo wann wie und oder der die das dem den bei auf fur zu mit von uber in am zum zur it is are was what how where please can you explain philips intellivue monitor gerat geraet device addendum handbuch manual".split(/\s+/));
function inspectIndex(data){
 if(!data||data.schemaVersion!==1||data.publisher!=="Philips"||data.partNumber!=="453665155181"||data.edition!=="2025-02"||data.pageCount!==4||!Array.isArray(data.entries)||data.entries.length!==5||!/^[a-f0-9]{64}$/.test(data.pdfSha256||""))throw new Error("PDF document identity invalid");
 if(!/^https:\/\/www\.documents\.philips\.com\/assets\/Addendum\/20250422\/[a-z0-9-]+\.pdf\?feed=ifu_docs_feed$/.test(data.sourceUrl))throw new Error("Source origin not verified");
 const ids=new Set();
 for(const e of data.entries){
  if(ids.has(e.id)||!Number.isInteger(e.pdfPage)||e.pdfPage<1||e.pdfPage>4||!e.summaryDe||!e.excerpt||e.excerpt.split(/\s+/).length>20||!Array.isArray(e.terms))throw new Error("Invalid page evidence");
  ids.add(e.id);
 }
 return data;
}
function find(data,question){
 inspectIndex(data);
 const q=normalize(question);
 const result=(status,heading,explanation,entry=null)=>({status,heading,explanation,entry});
 if(!q||q.length>450)return result("unknown","Frage fehlt","Bitte eine konkrete Frage zum Philips-Addendum stellen.");
 if(unsafe.test(q))return result("blocked","Sicherheitsgrenze","Keine Anleitung zur Alarmumgehung, Änderung klinischer Einstellungen oder Offenlegung geschützter Informationen.");
 if(excluded.test(q))return result("unknown","Falsche Quelle","Diese PDF-Referenz betrifft ein Philips-Addendum, keine anderen Hersteller oder internen Geräte-/Servicebestände.");
 const terms=q.split(" ").filter(t=>t.length>=3&&!generic.has(t));
 if(!terms.length)return result("unknown","Zu wenig Kontext","Bitte ein konkretes Thema nennen, beispielsweise Batterie, Umgebungstemperatur oder Alarmgrenzen.");
 const score=e=>{
  const words=new Set([...e.terms.flatMap(x=>normalize(x).split(" ")),...normalize(e.title).split(" "),...normalize(e.scope).split(" ")]);
  let n=0,matched=[];
  for(const t of terms){
   const hit=[...words].some(x=>x===t||(t.length>=5&&x.startsWith(t))||(x.length>=5&&t.startsWith(x)));
   if(hit){matched.push(t);n+=1}
  }
  const topic=new Set(["batterie","akku","battery","discharge","ladung","aufladen","temperature","temperatur","heat","hitze","ambient","alarmgrenzen","grenzwerte","limits","alarm","nanopod","capnography","kapnographie","co2","microstream","gase","gas","genauigkeit"]);
  if(!matched.some(w=>topic.has(w)||[...topic].some(t=>w.startsWith(t)&&w.length>=4)))return 0;
  return n;
 };
 const ranked=data.entries.map(e=>({entry:e,score:score(e)})).sort((a,b)=>b.score-a.score);
 if(!ranked[0]||ranked[0].score<1)return result("unknown","Keine passende Originalseite","Das geprüfte Addendum enthält nur fünf ausgewählte Passagen. Ich habe dazu keine ausreichend passende Fundstelle.");
 // A question that directly names a variant should not silently use content restricted to another family.
 if(/\b(?:mx100|mx400|mx750|mx850|x3)\b/.test(q)&&ranked[0].entry.scope.includes("6100/6300/6500")&&ranked[0].entry.id!=="alarm-limits"){
  return result("unknown","Andere Gerätefamilie","Diese Passage ist ausdrücklich für eine andere Gerätegruppe gekennzeichnet.");
 }
 const entry=ranked[0].entry;
 return {...result("evidence",entry.title,"Knapper aus dem Original-PDF extrahierter Textausschnitt; Quellenrelevanz vor Einsatz immer prüfen.",entry),
   citation:{document:data.sourceTitle,partNumber:data.partNumber,edition:data.edition,pdfPage:entry.pdfPage,sha256:data.pdfSha256,scope:entry.scope,url:data.sourceUrl+"#page="+entry.pdfPage},
   answer:entry.summaryDe,excerpt:entry.excerpt};
}
return {inspectIndex,find,normalize};
});